// ---------- wadi in doorsnede ----------
// (x, y) = midden op tegelhoogte, w = breedte; o.water 0..1 (peil in de wadi), o.instroom 0..1 (pijltjes van de tegels),
// o.zak 0..1 (water zakt de bodem in), o.t
