    const [a1, a2] = _ik(T[0] - sx, T[1] - sy, A1, A2), ex = sx + Math.sin(a1) * A1, ey = sy + Math.cos(a1) * A1, hx = ex + Math.sin(a2) * A2, hy = ey + Math.cos(a2) * A2;
