      tu2_bodemDruppel(ctx, 960, 1440, 1500, { u: 1, worm: true });
      tu2_wadi(ctx, 960, 520, 1500, { water, instroom: fase(t, q.at('stroomt', 1), q.at('zakt', 1) + 0.5, 0.5), zak: fase(t, q.at('zakt', 1), q.at('droog', 1) + 0.6, 0.5), t });
